  function forcarAtualizacao() {
      if (!painelPodeConsultar()) {
          renderizarCategoria();
          return;
      }
      limparTodosOsCaches();
      renderizarCategoria();
  }

  function atualizarConexaoSse() {
      if (!painelPodeConsultar()) {
          if (sse) {
              sse.close();
              sse = null;
          }
          return;
      }
      if (sse) return;
      sse = new EventSource('/api/vagas/stream');
      sse.addEventListener('vagas', () => forcarAtualizacao());
      sse.onmessage = () => forcarAtualizacao();
      sse.onerror = () => {};
  }

  hidratarCachePersistente();
  renderizarCategoria();
  let cicloTimer = setInterval(avancarCiclo, TEMPO_POR_TELA);

  function irParaIndice(novoIndice) {
      indiceAtual = (novoIndice + categorias.length) % categorias.length;
      renderizarCategoria();
      iniciarTimer();
  }

  document.getElementById('btn-prev').addEventListener('click', () => {
      irParaIndice(indiceAtual - 1);
  });
  document.getElementById('btn-next').addEventListener('click', () => {
      irParaIndice(indiceAtual + 1);
  });

  let hideButtonsTimer;
  function mostrarBotoesTemporario() {
      const nav = document.getElementById('nav-buttons');
      nav.classList.add('show');
      clearTimeout(hideButtonsTimer);
      hideButtonsTimer = setTimeout(() => nav.classList.remove('show'), 1200);
  }
  window.addEventListener('mousemove', mostrarBotoesTemporario);
  window.addEventListener('touchstart', mostrarBotoesTemporario, { passive: true });
  window.addEventListener('pointerdown', registrarAtividadeUsuario, { passive: true });
  window.addEventListener('touchstart', registrarAtividadeUsuario, { passive: true });
  window.addEventListener('keydown', registrarAtividadeUsuario);
  window.addEventListener('mousemove', registrarAtividadeUsuario);
  window.addEventListener('scroll', registrarAtividadeUsuario, { passive: true });
  window.addEventListener('resize', atualizarAlturaApp);
  window.addEventListener('orientationchange', atualizarAlturaApp);
  if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', atualizarAlturaApp);
  }
  function setInteractionLock(locked) {
      const blocker = document.getElementById('interaction-blocker');
      const btn = document.getElementById('btn-lock');
      if (!blocker || !btn) return;
      blocker.hidden = !locked;
      btn.setAttribute('aria-pressed', locked ? 'true' : 'false');
      btn.setAttribute('aria-label', locked ? 'Desbloquear interacao' : 'Bloquear interacao');
      btn.setAttribute('title', locked ? 'Desbloquear interacao' : 'Bloquear interacao');
      btn.innerHTML = locked
          ? '<i class="bi bi-lock-fill" aria-hidden="true"></i>'
          : '<i class="bi bi-unlock" aria-hidden="true"></i>';
  }

  function alternarInteractionLock() {
      const blocker = document.getElementById('interaction-blocker');
      if (!blocker) return;
      setInteractionLock(blocker.hidden);
  }

  document.getElementById('btn-fullscreen').addEventListener('click', alternarTelaCheia);
  document.getElementById('btn-lock').addEventListener('click', alternarInteractionLock);
  document.addEventListener('fullscreenchange', atualizarBotaoTelaCheia);
  document.addEventListener('webkitfullscreenchange', atualizarBotaoTelaCheia);
  atualizarAlturaApp();
  atualizarBotaoTelaCheia();
  atualizarQrRodape();
  agendarAutoRefreshPorInatividade();
  setInterval(atualizarQrRodape, TEMPO_ATUALIZAR_QR);
  pingHealth();
  setInterval(pingHealth, KEEPALIVE_MS);
  atualizarConexaoSse();
  setInterval(atualizarConexaoSse, 60000);
